'use strict';

const fs = require('node:fs'); const path = require('node:path');
const { immutableCopy } = require('../contracts/immutable'); const { assertProductSlug, getProductPath } = require('../state/product-state');
const DASHBOARDS = Object.freeze({ instagram: { source: '.claude/skills/instagram-dashboard', provider: 'apify', input: 'IG_USER', output: 'entregas/instagram-dashboard/insights.json' }, tiktok: { source: '.claude/skills/tiktok-dashboard', provider: 'apify', input: 'TIKTOK_USER', output: 'entregas/tiktok-dashboard/insights.json' }, youtube: { source: '.claude/skills/youtube-dashboard', provider: 'apify', input: 'YOUTUBE_CHANNEL', output: 'entregas/youtube-dashboard/insights.json' }, linkedin: { source: '.claude/skills/linkedin-dashboard', provider: 'apify', input: 'LINKEDIN_PROFILE', output: 'entregas/linkedin-dashboard/insights.json' } });
function descriptor(platform) { const item = DASHBOARDS[platform]; if (!item) throw new Error('unknown social dashboard platform'); return immutableCopy({ platform, source: item.source, provider: item.provider, capability: 'research.fetch', logical_secret: 'APIFY_API_TOKEN', inputs: [item.input], normalization: 'normalized social metrics JSON', outputs: [item.output], cache: 'product-local', error_behavior: 'preserve_existing_cache', status: 'READY_EXTERNAL' }); }
function prepareDashboard({ platform, secretProvider, provider_error = false }) { const value = descriptor(platform); if (!secretProvider || !secretProvider.has_secret(value.logical_secret)) return immutableCopy({ ...value, run_status: 'blocked', error: 'secret_unavailable', external_executable: false }); if (provider_error) return immutableCopy({ ...value, run_status: 'error', error: 'provider_error', external_executable: false }); return immutableCopy({ ...value, run_status: 'dry_run', data: { metrics: [], normalized: true }, error: null, external_executable: false }); }
function cachePath({ projectRoot, product_slug, platform }) { const config = descriptor(platform); return path.join(getProductPath(assertProductSlug(product_slug), projectRoot), config.outputs[0]); }
function writeMockDashboardCache({ projectRoot, product_slug, platform, metrics = [] }) { const output = cachePath({ projectRoot, product_slug, platform }); const data = immutableCopy({ platform, metrics, normalized: true, provider: 'apify', mode: 'mock' }); fs.mkdirSync(path.dirname(output), { recursive: true }); fs.writeFileSync(output, `${JSON.stringify(data, null, 2)}\n`, 'utf8'); return immutableCopy({ status: 'success', cache_path: output, data }); }
function preserveDashboardCacheOnProviderError({ projectRoot, product_slug, platform }) { const output = cachePath({ projectRoot, product_slug, platform }); return immutableCopy({ status: 'source_failed', error: 'provider_error', cache_path: output, preserved_existing_cache: fs.existsSync(output) }); }
module.exports = { DASHBOARDS, descriptor, prepareDashboard, cachePath, writeMockDashboardCache, preserveDashboardCacheOnProviderError };
